import OwnerSidebar from '../components/OwnerSidebar';
import VetSidebar from '../components/VetSidebar';
import supabase from '../supabaseClient';

  // Fetch messages initially and set up polling
  const fetchMessages = async () => {
    try {
      const { data, error } = await supabase
        .from('chat_messages')
        .select('*')
        .eq('consultationId', consultationId)
        .order('createdAt', { ascending: true });

      if (error) throw error;
      setMessages(data || []);
    } catch (err) {
      console.error("Error fetching chat messages", err);
    } finally {
      setLoading(false);
    }
  };

  fetchMessages();

  // Set up Supabase Realtime Subscription
  const subscription = supabase
    .channel(`chat_messages_${consultationId}`)
    .on('postgres_changes', { 
      event: 'INSERT', 
      schema: 'public', 
      table: 'chat_messages',
      filter: `consultationId=eq.${consultationId}`
    }, (payload) => {
      setMessages((prev) => {
         // Prevent duplicates if optimistic UI already added it
         if (prev.some(m => m.id === payload.new.id || m.message === payload.new.message)) {
           return prev;
         }
         return [...prev, payload.new];
      });
    })
    .subscribe();

  return () => {
    supabase.removeChannel(subscription);
  };
}, [consultationId, navigate]);

