  // Fetch messages initially and set up polling
  const initializeChat = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('chat_messages')
        .select('*')
        .eq('conversationId', consultationId)
        .order('createdAt', { ascending: true });

      if (error) throw error;
      setMessages(data || []);
      console.log("[Chat Debug] Initial fetch success, messages:", data?.length);
    } catch (err) {
      console.error("[Chat Debug] Error fetching chat messages:", err);
    } finally {
      setLoading(false);
    }

    // Set up Supabase Realtime Subscription AFTER fetching
    console.log("[Chat Debug] Setting up realtime subscription for conversationId:", consultationId);
    const subscription = supabase
      .channel(`chat_messages_${consultationId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'chat_messages',
        filter: `conversationId=eq.${consultationId}`
      }, (payload) => {
        console.log("[Chat Debug] Realtime INSERT received:", payload);
        setMessages((prev) => {
           // Prevent duplicates if optimistic UI already added it
           if (prev.some(m => m.id === payload.new.id || m.message === payload.new.message)) {
             console.log("[Chat Debug] Duplicate message ignored");
             return prev;
           }
           return [...prev, payload.new];
        });
      })
      .subscribe((status) => {
        console.log("[Chat Debug] Subscription status:", status);
      });

    return subscription;
  };

  let activeSubscription = null;
  initializeChat().then(sub => { activeSubscription = sub; });

  return () => {
    if (activeSubscription) {
      console.log("[Chat Debug] Unsubscribing from realtime channel");
      supabase.removeChannel(activeSubscription);
    }
  };
}, [consultationId, navigate]);

const handleSend = async (e) => {
  e.preventDefault();
  if (!input.trim() || !user || !consultationId) return;

  const msgText = input;
  setInput('');

  const senderRole = isDoctor ? 'vet' : 'owner';
  const receiverIdObj = consultation ? (isDoctor ? consultation.ownerId : consultation.vetId) : null;
  const receiverId = typeof receiverIdObj === 'object' && receiverIdObj ? receiverIdObj._id || receiverIdObj.id : receiverIdObj;

  const newMsg = {
    senderId: user._id || user.id,
    receiverId: receiverId,
    senderName: user.name,
    senderRole: senderRole,
    message: msgText,
    conversationId: consultationId
  };

  console.log("[Chat Debug] Sending message:", newMsg);

  // Optimistic UI update
  setMessages(prev => [...prev, { ...newMsg, _id: Date.now(), createdAt: new Date().toISOString() }]);

  try {
    const { data, error } = await supabase
      .from('chat_messages')
      .insert([{
         ...newMsg,
         createdAt: new Date().toISOString()
      }])
      .select()
      .single();

    if (error) {
      console.error("[Chat Debug] Supabase Insert Error:", error);
      throw error;
    }

    console.log("[Chat Debug] Message inserted successfully:", data.id);

    // We will let the realtime subscription handle adding it, but we already optimistically added it
    // Replace optimistic message with real message from DB (to get correct ID)
    setMessages(prev => prev.map(m => m._id === newMsg._id ? data : m));
  } catch (err) {
    console.error("[Chat Debug] Error sending message:", err);
  }
};

